{
  "technical_and_design_decisions": [
    "Target Java 17+ with Spring Framework 6 as the baseline platform, consistent with the specification's platform statement.",
    "U1: Implement the Receptor client as a standalone Java library exposing a typed API (tasks, desired/actual LRPs); use Spring's REST client abstraction (RestTemplate/WebClient) with Jackson-based DTOs for JSON serialization, and design it so XD components can consume it as a Spring bean.",
    "U2: Introduce clean repository interfaces for stream and job definitions that contain no module-deployment types; move deployment concerns into a separate deployment service layer; preserve existing persistence behavior while changing only structure and dependencies.",
    "U3: Define a runtime SPI as a set of Java interfaces (e.g., StreamDeployer, JobDeployer, ModuleDeployer) with a service-loading/auto-configuration mechanism; select the implementation (CF, local/on-prem, Mesos) via externalized configuration and Spring profiles.",
    "U4: Persist stream metadata in a replicated, highly available store (ZooKeeper, consistent with XD runtime coordination) behind the new repository abstraction; implement recovery logic that on restart/failure re-reads metadata and redeploys/reconnects the streaming pipeline.",
    "U6: Integrate Spark/Spark Streaming as XD modules (processor/sink) using the Spark Streaming receiver API, packaged and configured via standard XD module options, tested against a local Spark runtime.",
    "U8: Replace the free-form --args passthrough with first-class, named, validated module options for all import options, declared via module option metadata so the shell can parse, validate, and document them.",
    "All reference documentation (U5, U7, plus updates for U8 and U6) is written in AsciiDoc in the project's reference guide, with runnable, verified examples."
  ],
  "assumptions": [
    "An existing Spring XD codebase, build system, CI pipeline, and test infrastructure are available, and the developer is already familiar with them.",
    "Effort estimates are net development effort in workdays (8 hours per day) for a single developer and exclude elapsed-time effects such as review wait times, meetings, and environment outages.",
    "The Receptor API is documented and reachable; integration testing uses a mock Receptor server plus one shared integration environment, which already exists.",
    "Scope includes unit and integration tests plus developer-written reference documentation; it excludes performance/load testing, security audits, and formal QA certification.",
    "U5, U7 are documentation-only; U5 and U7 code behavior already works and only needs verification of examples.",
    "For U8, only shell/command-line and module metadata changes are required; no graphical UI changes are in scope.",
    "The persistent store for U4 (ZooKeeper ensemble) is already provisioned in dev/test environments.",
    "Documentation is delivered in English only, as part of the source repository."
  ],
  "activities": [
    {
      "activity_id": "1.1",
      "activity_name": "Increment analysis and architecture alignment",
      "activity_description": "Analyze the eight user stories, map them onto the existing XD codebase, define package/API boundaries affected by the repository refactor (U2), SPI (U3), and persistence (U4) work, and produce a lightweight design note reviewed by self-check before coding.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "2.1",
      "activity_name": "U1 - Design Receptor client API and domain model",
      "activity_description": "Define the Java client interface and DTO/model classes for Receptor resources (tasks, desired LRPs, actual LRPs), including exception hierarchy.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "2.2",
      "activity_name": "U1 - Implement Receptor HTTP client",
      "activity_description": "Implement the REST client against the Receptor endpoints (CRUD for desired LRPs, task submission/cancellation, retrieval of actual LRP state) using Spring REST client support.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "2.3",
      "activity_name": "U1 - Serialization and error handling",
      "activity_description": "Implement Jackson mapping (including polymorphic/optional fields), response error mapping, timeouts, and retry-safe behavior for idempotent calls.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "2.4",
      "activity_name": "U1 - Client unit and integration tests",
      "activity_description": "Write unit tests with mocked HTTP layer and integration tests against a mock Receptor server plus a smoke test against a real endpoint.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "2.5",
      "activity_name": "U1 - Wire client into XD runtime",
      "activity_description": "Expose the client as a configurable Spring bean in XD, add configuration properties (endpoint, credentials), and verify end-to-end interaction with the Diego runtime via Receptor.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "3.1",
      "activity_name": "U2 - Analyze coupling and define new repository interfaces",
      "activity_description": "Inspect current stream/job definition repository usage, identify module-deployment dependencies, and define decoupled repository interfaces plus a separate deployment coordination service.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "3.2",
      "activity_name": "U2 - Refactor stream definition repository",
      "activity_description": "Refactor the stream definition repository implementation and its callers to the new deployment-free abstraction.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "3.3",
      "activity_name": "U2 - Refactor job definition repository",
      "activity_description": "Refactor the job definition repository implementation and its callers to the new deployment-free abstraction.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "3.4",
      "activity_name": "U2 - Migrate and extend tests",
      "activity_description": "Update existing unit/integration tests to the new structure and add regression tests proving repository behavior is unchanged.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "4.1",
      "activity_name": "U3 - Design runtime SPI contracts",
      "activity_description": "Define SPI interfaces (stream deployer, job deployer, module deployer, status/lifecycle operations) and their contract documentation, ensuring they cover CF, on-prem/local, and Mesos targets.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "4.2",
      "activity_name": "U3 - Implement SPI core and loading mechanism",
      "activity_description": "Implement the SPI core, auto-configuration, and service-loading mechanism that discovers and instantiates the selected implementation.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "4.3",
      "activity_name": "U3 - Adapt existing deployers to the SPI",
      "activity_description": "Adapt the existing CF and local/on-prem deployment logic into SPI implementations without behavior change.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "4.4",
      "activity_name": "U3 - Target-based selection and configuration",
      "activity_description": "Implement configuration properties/profiles that select the SPI implementation per deployment target, with sensible defaults and validation.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "4.5",
      "activity_name": "U3 - SPI tests",
      "activity_description": "Add unit tests for selection/loading logic and integration tests exercising each adapted implementation through the SPI.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "5.1",
      "activity_name": "U4 - Design persistence model and storage approach",
      "activity_description": "Design the persisted stream metadata schema (definition, deployment state, module bindings, offsets/checkpoint pointers) and confirm ZooKeeper as the backing store behind the repository abstraction.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "5.2",
      "activity_name": "U4 - Implement persistent stream repository",
      "activity_description": "Implement CRUD and query operations for persisted stream metadata, including optimistic concurrency handling and listeners for metadata changes.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "5.3",
      "activity_name": "U4 - Implement failure recovery and re-establishment",
      "activity_description": "Implement startup/admin-triggered recovery that reads persisted metadata and re-establishes streaming pipelines (redeploy modules, resume from last persisted state) after failure.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "5.4",
      "activity_name": "U4 - Persistence and failure-scenario tests",
      "activity_description": "Add unit tests, integration tests against an embedded ZooKeeper, and failure-injection tests (node restart, crash mid-deployment) validating recovery behavior.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "6.1",
      "activity_name": "U5 - Document quote escaping for Sqoop jobs",
      "activity_description": "Verify the double-escape behavior (e.g., \\\\\\\\N vs '\\N') with a real job submission, then write the reference documentation section with correct and incorrect examples.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "7.1",
      "activity_name": "U6 - Design Spark/Spark Streaming integration",
      "activity_description": "Design how Spark Streaming fits XD streaming pipelines (module roles, receiver approach, checkpointing, module options) consistent with the latest XD and Spark specs.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "7.2",
      "activity_name": "U6 - Implement Spark streaming modules",
      "activity_description": "Implement the Spark/Spark Streaming module(s) with configurable options, serialization handling, and lifecycle integration with XD's module container.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "7.3",
      "activity_name": "U6 - Test Spark pipelines end to end",
      "activity_description": "Test with a local Spark runtime: unit tests, module-level integration tests, and an end-to-end XD stream (source -> Spark processor -> sink), including failure/restart sanity checks.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "7.4",
      "activity_name": "U6 - Spark samples and documentation",
      "activity_description": "Create a runnable sample streaming pipeline and write reference documentation covering options, deployment, and limitations.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "8.1",
      "activity_name": "U7 - Verify nested batch job/workflow examples",
      "activity_description": "Build and run verified examples of nesting batch jobs and composed workflows in XD to ensure the documented steps actually work.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "8.2",
      "activity_name": "U7 - Write nested jobs/workflows documentation",
      "activity_description": "Write the reference documentation for nesting batch jobs and workflows, including diagrams/examples and common pitfalls.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "9.1",
      "activity_name": "U8 - Analyze current import options handling",
      "activity_description": "Catalog all import options currently passed via --args and define the named, typed option metadata that replaces them.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "9.2",
      "activity_name": "U8 - Implement parameterized import options",
      "activity_description": "Implement named, validated options for all import options in the affected modules, wiring them into module option metadata.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "9.3",
      "activity_name": "U8 - Update shell parsing and deprecate --args",
      "activity_description": "Update shell command parsing/validation, provide deprecation handling and migration guidance for existing --args usage.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "9.4",
      "activity_name": "U8 - Tests and documentation for new options",
      "activity_description": "Add/adjust tests for the new options and update reference docs and examples to use parameterized options.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "10.1",
      "activity_name": "Increment integration and regression testing",
      "activity_description": "Run cross-feature integration and regression testing of the whole increment (repository refactor + SPI + persistence + Receptor client + Spark modules + options changes), fix integration defects, and stabilize the build.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "10.2",
      "activity_name": "Release preparation and documentation review",
      "activity_description": "Final documentation proofreading, changelog/release notes, build packaging verification, and release readiness checks.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 92
  }
}

